package com.fitconnect.booking.api; import com.fitconnect.booking.domain.*; import java.math.BigDecimal; import java.time.LocalDateTime; public record BookingResponse(Long id,String bookingReference,Long userId,String userEmail,String userName,Long classId,String className,LocalDateTime classDate,String instructor,BigDecimal price,Integer numberOfSpots,BigDecimal totalAmount,LocalDateTime bookingDate,BookingStatus status,LocalDateTime paymentDeadline,LocalDateTime cancellationDeadline){public static BookingResponse from(Booking b){return new BookingResponse(b.getId(),b.getBookingReference(),b.getUserId(),b.getUserEmail(),b.getUserName(),b.getClassId(),b.getClassName(),b.getClassDate(),b.getInstructor(),b.getPrice(),b.getNumberOfSpots(),b.getTotalAmount(),b.getBookingDate(),b.getStatus(),b.getPaymentDeadline(),b.getCancellationDeadline());}}
